  VALUES (v_test, $q$listening1$q$, $q$Listening — Conversation 1$q$, $q$listening$q$, NULL, $q$لا يتضمن هذا القسم ملفًا صوتيًا بعد — اقرأ نص التسجيل كما لو كنت تسمعه (مرة واحدة فقط في الامتحان الحقيقي)، ثم أجب عن الأسئلة.$q$, $q$Conversation 1
Man: Hi, Sofia. Did you book the meeting room for tomorrow's presentation?
Woman: Yes, I reserved Room 4 for ten o'clock, but I just heard that the projector there isn't working.
Man: Oh no. Can we move to Room 6? It's a bit smaller, but the equipment is new.
Woman: Good idea. I'll call the front desk and change the booking now. How many people are coming?
Man: About twelve, I think. Room 6 holds fifteen, so that should be fine.$q$, NULL, 3)
  RETURNING id INTO v_sec;
  VALUES (v_test, v_sec, $q$What problem do the speakers discuss?$q$, 'multiple_choice', 1, $q$The projector in Room 4 isn't working.$q$, 0) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What will the woman do next?$q$, 'multiple_choice', 1, $q$'I'll call the front desk and change the booking now.'$q$, 1) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$How many people does the man expect?$q$, 'multiple_choice', 1, $q$About twelve.$q$, 2) RETURNING id INTO v_q;
  VALUES (v_test, $q$listening2$q$, $q$Listening — Conversation 2$q$, $q$listening$q$, NULL, $q$لا يتضمن هذا القسم ملفًا صوتيًا بعد — اقرأ نص التسجيل كما لو كنت تسمعه (مرة واحدة فقط في الامتحان الحقيقي)، ثم أجب عن الأسئلة.$q$, $q$Conversation 2
Woman: Good afternoon. I'd like to return this jacket. I bought it last week, but it's too small.
Man: No problem. Do you have the receipt?
Woman: Yes, here it is.
Man: Thank you. Would you like a refund, or would you prefer to exchange it for a larger size?
Woman: I'd like a larger size, if you have one in blue.
Man: Let me check. Yes, we have a large in blue. I'll get it for you.$q$, NULL, 4)
  RETURNING id INTO v_sec;
