  VALUES (v_test, $q$uoe$q$, $q$Use of English — Multiple-choice$q$, $q$language$q$, NULL, $q$اختر الإجابة الصحيحة لإكمال كل جملة.$q$, NULL, NULL, 0)
  RETURNING id INTO v_sec;
