  VALUES (v_test, v_sec, $q$What is free for new members?$q$, 'multiple_choice', 1, $q$'Your first two weeks free'.$q$, 1) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$There is a joining fee.$q$, 'multiple_choice', 1, $q$'There is no joining fee.'$q$, 2) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Group classes cost extra.$q$, 'multiple_choice', 1, $q$Classes cost £5 each.$q$, 3) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What should members bring?$q$, 'multiple_choice', 1, $q$'Bring your own towel and a bottle of water.'$q$, 4) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Children under 16 may use the gym alone.$q$, 'multiple_choice', 1, $q$They cannot use it without an adult.$q$, 5) RETURNING id INTO v_q;
