-- Reading Practice: Working from Home
DO $ep$ DECLARE v_test UUID; v_sec UUID; v_q UUID; BEGIN
      total_questions, passing_score, is_active, is_skill_practice, skill, content_kind)
  VALUES ($q$Reading Practice: Working from Home$q$, $q$نص قصير مع أسئلة استيعاب — حوالي 6 دقائق$q$, $q$skill_en_reading_remote_work$q$, 'en', $q$B1$q$, 6,
      6, 60, TRUE, TRUE, $q$reading$q$, $q$quiz$q$)
  ON CONFLICT (test_type) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
      track = 'en', level = EXCLUDED.level, duration_minutes = EXCLUDED.duration_minutes,
      total_questions = EXCLUDED.total_questions, passing_score = EXCLUDED.passing_score,
      is_active = TRUE, is_skill_practice = EXCLUDED.is_skill_practice, skill = EXCLUDED.skill,
      content_kind = EXCLUDED.content_kind
  RETURNING id INTO v_test;
  DELETE FROM public.test_sections WHERE test_id = v_test;
  DELETE FROM public.test_writing_prompts WHERE test_id = v_test;
  VALUES (v_test, $q$reading1$q$, $q$Reading$q$, $q$reading$q$, NULL, NULL, $q$More and more people now work from home at least some of the week. Employees say the biggest advantage is saving time: without a daily commute, many gain one or two hours. They also report being able to concentrate better without office noise. Companies, too, can benefit, because they need less office space.

However, remote work has drawbacks. Some people feel lonely and find it hard to separate work from private life, especially if they do not have a separate room for working. Managers sometimes worry that it is harder to build a team when people rarely meet. As a result, many firms now choose a hybrid model: two or three days at home and the rest in the office.$q$, NULL, 0)
  RETURNING id INTO v_sec;
  VALUES (v_test, v_sec, $q$What is the biggest advantage for employees, according to the text?$q$, 'multiple_choice', 1, $q$They gain one or two hours without a daily commute.$q$, 0) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Companies can benefit by needing less office space.$q$, 'multiple_choice', 1, $q$The text says this directly.$q$, 1) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$All employees find it easy to separate work and private life.$q$, 'multiple_choice', 1, $q$Some find it hard.$q$, 2) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What is a hybrid model?$q$, 'multiple_choice', 1, $q$'Two or three days at home and the rest in the office.'$q$, 3) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Why do managers sometimes worry about remote work?$q$, 'multiple_choice', 1, $q$'It is harder to build a team when people rarely meet.'$q$, 4) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$The text says remote work makes employees earn less.$q$, 'multiple_choice', 1, $q$Salaries are not mentioned.$q$, 5) RETURNING id INTO v_q;
END $ep$;

-- Reading Practice (TOEFL style): Glaciers
DO $ep$ DECLARE v_test UUID; v_sec UUID; v_q UUID; BEGIN
      total_questions, passing_score, is_active, is_skill_practice, skill, content_kind)
  VALUES ($q$Reading Practice (TOEFL style): Glaciers$q$, $q$نص قصير مع أسئلة استيعاب — حوالي 6 دقائق$q$, $q$skill_en_reading_toefl_glaciers$q$, 'en', $q$B2$q$, 6,
      6, 60, TRUE, TRUE, $q$reading$q$, $q$quiz$q$)
  ON CONFLICT (test_type) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
      track = 'en', level = EXCLUDED.level, duration_minutes = EXCLUDED.duration_minutes,
      total_questions = EXCLUDED.total_questions, passing_score = EXCLUDED.passing_score,
      is_active = TRUE, is_skill_practice = EXCLUDED.is_skill_practice, skill = EXCLUDED.skill,
      content_kind = EXCLUDED.content_kind
  RETURNING id INTO v_test;
  DELETE FROM public.test_sections WHERE test_id = v_test;
  DELETE FROM public.test_writing_prompts WHERE test_id = v_test;
  VALUES (v_test, $q$reading1$q$, $q$Reading$q$, $q$reading$q$, NULL, NULL, $q$Glaciers are large masses of ice that form where more snow falls in winter than melts in summer. Over many years, the weight of the accumulating snow compresses the lower layers into dense ice, and when the ice becomes thick enough, it begins to flow slowly downhill under its own weight. Some glaciers move only a few centimetres a day, while others, such as those in Greenland, can advance several metres daily.

As glaciers move, they erode the landscape beneath them. Rocks frozen into the base of the ice scrape the valley floor like sandpaper, widening and deepening it into a characteristic U shape. When the ice finally melts, it leaves behind lakes, ridges and piles of rock that were carried along. Many of the lakes in northern Europe and Canada were formed in this way during the last Ice Age.$q$, NULL, 0)
  RETURNING id INTO v_sec;
  VALUES (v_test, v_sec, $q$According to the passage, how do glaciers form?$q$, 'multiple_choice', 1, $q$They form where more snow falls in winter than melts in summer.$q$, 0) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$The word "compresses" in the passage is closest in meaning to…$q$, 'multiple_choice', 1, $q$'Compress' means to press into a smaller space.$q$, 1) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What shape do glaciers give to the valleys they pass through?$q$, 'multiple_choice', 1, $q$The valley is widened and deepened into a U shape.$q$, 2) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What do rocks in the base of the ice do?$q$, 'multiple_choice', 1, $q$They scrape the valley floor like sandpaper.$q$, 3) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Which of the following is TRUE about glaciers in Greenland?$q$, 'multiple_choice', 1, $q$Greenland glaciers can advance several metres daily.$q$, 4) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What is mentioned as a result of melting glaciers?$q$, 'multiple_choice', 1, $q$The melted ice leaves behind lakes, ridges and piles of rock.$q$, 5) RETURNING id INTO v_q;
END $ep$;

