  ON CONFLICT (test_type) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
      track = 'en', level = EXCLUDED.level, duration_minutes = EXCLUDED.duration_minutes,
      total_questions = EXCLUDED.total_questions, passing_score = EXCLUDED.passing_score,
      is_active = TRUE, is_skill_practice = EXCLUDED.is_skill_practice, skill = EXCLUDED.skill,
      content_kind = EXCLUDED.content_kind
  RETURNING id INTO v_test;
  DELETE FROM public.test_sections WHERE test_id = v_test;
  DELETE FROM public.test_writing_prompts WHERE test_id = v_test;
  VALUES (v_test, $q$listening1$q$, $q$Listening$q$, $q$listening$q$, NULL, $q$لا يتضمن هذا القسم ملفًا صوتيًا بعد — اقرأ نص التسجيل كما لو كنت تسمعه (مرة واحدة فقط في الامتحان الحقيقي)، ثم أجب عن الأسئلة.$q$, $q$Conversation at check-in
Agent: Good morning. Where are you flying to today?
Passenger: To Madrid, flight IB 3411.
Agent: May I see your passport, please? Thank you. Do you have any luggage to check in?
Passenger: Yes, one suitcase.
Agent: Please put it on the scale. It's twenty-two kilos, which is fine. Would you like a window or an aisle seat?
Passenger: A window seat, please.
Agent: Here is your boarding pass. Boarding starts at ten forty at gate B12.
Passenger: Thank you. Is the flight on time?
Agent: Yes, it leaves at eleven fifteen.$q$, NULL, 0)
  RETURNING id INTO v_sec;
  VALUES (v_test, v_sec, $q$Where is the passenger flying?$q$, 'multiple_choice', 1, $q$To Madrid.$q$, 0) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$How much does the suitcase weigh?$q$, 'multiple_choice', 1, $q$Twenty-two kilos.$q$, 1) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Which seat does the passenger choose?$q$, 'multiple_choice', 1, $q$A window seat.$q$, 2) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$When does boarding start?$q$, 'multiple_choice', 1, $q$Boarding starts at ten forty.$q$, 3) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Which gate is it?$q$, 'multiple_choice', 1, $q$Gate B12.$q$, 4) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$The flight is delayed.$q$, 'multiple_choice', 1, $q$It is on time, leaving at eleven fifteen.$q$, 5) RETURNING id INTO v_q;
END $ep$;

