  ON CONFLICT (test_type) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
      track = 'en', level = EXCLUDED.level, duration_minutes = EXCLUDED.duration_minutes,
      total_questions = EXCLUDED.total_questions, passing_score = EXCLUDED.passing_score,
      is_active = TRUE, is_skill_practice = EXCLUDED.is_skill_practice, skill = EXCLUDED.skill,
      content_kind = EXCLUDED.content_kind
  RETURNING id INTO v_test;
  DELETE FROM public.test_sections WHERE test_id = v_test;
  DELETE FROM public.test_writing_prompts WHERE test_id = v_test;
  VALUES (v_test, $q$listening1$q$, $q$Listening$q$, $q$listening$q$, NULL, $q$لا يتضمن هذا القسم ملفًا صوتيًا بعد — اقرأ نص التسجيل كما لو كنت تسمعه (مرة واحدة فقط في الامتحان الحقيقي)، ثم أجب عن الأسئلة.$q$, $q$Interview
Interviewer: Thank you for coming, Ms Haddad. Could you tell me about your previous job?
Candidate: Of course. For the past three years I've worked as a sales assistant in a large electronics store. I helped customers choose products and trained new colleagues.
Interviewer: Why are you leaving?
Candidate: I'm looking for more responsibility, and I'd like to work in a role where I can use my languages. I speak English, French and Arabic.
Interviewer: That's very useful for us. This position involves working some weekends. Is that a problem?
Candidate: Not at all. I'm flexible.
Interviewer: Excellent. When could you start?
Candidate: I have to give one month's notice, so I could begin on the first of next month.$q$, NULL, 0)
  RETURNING id INTO v_sec;
  VALUES (v_test, v_sec, $q$How long has the candidate worked at her current job?$q$, 'multiple_choice', 1, $q$'For the past three years.'$q$, 0) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What did she do in her previous job?$q$, 'multiple_choice', 1, $q$She was a sales assistant in an electronics store.$q$, 1) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Why does she want to leave?$q$, 'multiple_choice', 1, $q$More responsibility and use of her languages.$q$, 2) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Which languages does she speak?$q$, 'multiple_choice', 1, $q$English, French and Arabic.$q$, 3) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$She cannot work at weekends.$q$, 'multiple_choice', 1, $q$'Not at all. I'm flexible.'$q$, 4) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$When can she start?$q$, 'multiple_choice', 1, $q$She has to give one month's notice.$q$, 5) RETURNING id INTO v_q;
END $ep$;

-- Listening Practice (TOEFL style): Short Lecture on Pollination
DO $ep$ DECLARE v_test UUID; v_sec UUID; v_q UUID; BEGIN
      total_questions, passing_score, is_active, is_skill_practice, skill, content_kind)
  VALUES ($q$Listening Practice (TOEFL style): Short Lecture on Pollination$q$, $q$حوار أو حديث قصير مع أسئلة استيعاب — حوالي 6 دقائق$q$, $q$skill_en_listening_lecture_bees$q$, 'en', $q$B2$q$, 6,
      6, 60, TRUE, TRUE, $q$listening$q$, $q$quiz$q$)
  ON CONFLICT (test_type) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
      track = 'en', level = EXCLUDED.level, duration_minutes = EXCLUDED.duration_minutes,
      total_questions = EXCLUDED.total_questions, passing_score = EXCLUDED.passing_score,
      is_active = TRUE, is_skill_practice = EXCLUDED.is_skill_practice, skill = EXCLUDED.skill,
      content_kind = EXCLUDED.content_kind
  RETURNING id INTO v_test;
  DELETE FROM public.test_sections WHERE test_id = v_test;
  DELETE FROM public.test_writing_prompts WHERE test_id = v_test;
  VALUES (v_test, $q$listening1$q$, $q$Listening$q$, $q$listening$q$, NULL, $q$لا يتضمن هذا القسم ملفًا صوتيًا بعد — اقرأ نص التسجيل كما لو كنت تسمعه (مرة واحدة فقط في الامتحان الحقيقي)، ثم أجب عن الأسئلة.$q$, $q$Lecture
Professor: Today I'd like to talk about pollination. Many flowering plants cannot produce seeds unless pollen is transferred from one flower to another. Wind can do this for plants such as grasses, but around three quarters of the world's major food crops rely at least partly on animals, mostly insects. Bees are the most important pollinators because they feed on nectar and pollen throughout their lives and visit large numbers of flowers.
This relationship benefits both sides: the plant is pollinated, and the bee gets food. However, in recent decades, bee populations have declined in many regions, largely because of habitat loss and pesticides. Without bees, farmers would need to pollinate some crops by hand, as is already happening in parts of China, which is extremely costly. For next week, prepare a short summary of one study on bee decline.$q$, NULL, 0)
  RETURNING id INTO v_sec;
  VALUES (v_test, v_sec, $q$What is the main topic of the lecture?$q$, 'multiple_choice', 1, $q$The professor introduces pollination.$q$, 0) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Which plants are pollinated by wind?$q$, 'multiple_choice', 1, $q$Wind pollinates plants such as grasses.$q$, 1) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$Why are bees the most important pollinators?$q$, 'multiple_choice', 1, $q$They feed on nectar and pollen and visit large numbers of flowers.$q$, 2) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What has caused the decline in bee populations?$q$, 'multiple_choice', 1, $q$'Largely because of habitat loss and pesticides.'$q$, 3) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What is happening in parts of China, according to the professor?$q$, 'multiple_choice', 1, $q$Crops are pollinated by hand, which is extremely costly.$q$, 4) RETURNING id INTO v_q;
  VALUES (v_test, v_sec, $q$What are the students asked to do?$q$, 'multiple_choice', 1, $q$Prepare a short summary of one study on bee decline.$q$, 5) RETURNING id INTO v_q;
END $ep$;

